<script setup lang="ts">
import {computed,ref} from 'vue'
import type {ContractPage,EmploymentContract} from '../complianceTypes'
import {storeToday} from '../time'
const props=defineProps<{page:ContractPage;english:boolean;busy:boolean}>(),emit=defineEmits<{save:[body:unknown]}>()
const latest=props.page.items.at(-1),previous=props.page.items.filter(c=>!props.page.companyId||c.companyId===props.page.companyId).at(-1),selected=ref(props.page.policies.filter(p=>p.status==='published').at(-1)),on=storeToday()
const draft=ref({expectedVersion:props.page.version??latest?.version??0,effectiveFrom:on,serviceStart:previous?.serviceStart||props.page.suggestedServiceStart||on,dailyHours:previous?.dailyHours||8,weeklyHours:previous?.weeklyHours||40,weeklyDays:previous?.weeklyDays||5,comparableDailyHours:previous?.comparableDailyHours||8,comparableWeeklyHours:previous?.comparableWeeklyHours||44,category:previous?.category||'non_workman',evidence:''})
const partTime=computed(()=>!!selected.value&&draft.value.weeklyHours<selected.value.rules.partTimeBelowHours)
function save(){if(selected.value)emit('save',{...draft.value,policyId:selected.value.id,policyVersion:selected.value.version})}
</script>
<template><form @submit.prevent="save"><fieldset :disabled="busy"><p class="wf-hint">{{english?'Pay basis is independent of part-time status. Use the signed contract and actual job duties.':'月薪／日薪／时薪不决定是否兼职；以签订合同及实际岗位职责核对。'}}</p><label>{{english?'Published policy':'采用已发布政策'}}<select v-model="selected" required><option v-for="p in page.policies.filter(p=>p.status==='published')" :key="p.id+':'+p.version" :value="p">{{p.name}} · v{{p.version}} · {{p.effectiveFrom}} – {{p.effectiveTo}}</option></select></label><div class="wf-grid"><label>{{english?'Effective from':'合同生效日'}}<input v-model="draft.effectiveFrom" type="date" :min="previous?.effectiveFrom" required></label><label>{{english?'Continuous service starts':'连续服务起算日'}}<input v-model="draft.serviceStart" type="date" :max="draft.effectiveFrom" required></label><label>{{english?'Hours per day':'合同每日工作小时'}}<input v-model.number="draft.dailyHours" type="number" min="0.1" max="24" step="0.1" required></label><label>{{english?'Hours per week':'合同每周工作小时'}}<input v-model.number="draft.weeklyHours" type="number" min="0.1" max="168" step="0.1" required></label><label>{{english?'Days per week':'合同每周工作天数'}}<input v-model.number="draft.weeklyDays" type="number" min="0.1" max="7" step="0.1" required></label><label>{{english?'Comparable full-time hours/day':'同类全职每日小时'}}<input v-model.number="draft.comparableDailyHours" type="number" min="0.1" max="24" step="0.1" required></label><label>{{english?'Comparable full-time hours/week':'同类全职每周小时'}}<input v-model.number="draft.comparableWeeklyHours" type="number" min="0.1" max="168" step="0.1" required></label><label>{{english?'Actual job category':'实际工作类别'}}<select v-model="draft.category"><option value="workman">{{english?'Workman':'劳工'}}</option><option value="non_workman">{{english?'Non-workman':'非劳工'}}</option><option value="manager">{{english?'Manager / executive':'经理／主管'}}</option></select></label></div><p role="status">{{partTime?(english?'Part-time: leave recorded in hours':'兼职：假期以小时记账'):(english?'Full-time: leave recorded in days':'全职：假期以天记账')}} · {{english?'Statutory overtime also depends on basic wages and job category.':'法定加班资格还须结合基本工资及工作类别判定。'}}</p><label>{{english?'Contract and category evidence':'合同与类别核对依据'}}<textarea v-model="draft.evidence" maxlength="1000" rows="3" required/></label><footer class="wf-form-actions"><button class="primary" :disabled="!selected">{{english?'Confirm new contract version':'确认合同新版本'}}</button></footer><p v-if="!page.policies.some(p=>p.status==='published')" class="wf-hint">{{english?'Ask head office to publish the policy first.':'请先由总部核对并发布政策。'}}</p></fieldset></form></template>
